impl<T: gx::Real> Scalar<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (4 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Scalar<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t1 * t3;
        Scalar::from_coeffs([t4])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Scalar::from_coeffs([t0]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Scalar::from_coeffs(c).normalized()
    }

}

impl<T: gx::Coef> gx::NewtonStep for Scalar<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t3 = x[0] * T::from_ratio(3, 2);
        let t4 = (-t1).mul_add(T::from_ratio(1, 2), t3);
        Scalar::from_coeffs([t4])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

#[doc = "A line `a x + b y + c = 0`, stored as `a e1 + b e2 + c e0`: the vectors (grade 1) of plane-based PGA. As a versor it is a reflection."]
///
/// Blades, in coefficient order: `[e1, e2, e0]`.
///
/// `S` lists the open slots: `Line` (that is, `Line<()>`) is a value, `Line<(A,)>` a
/// linear map from `A`, `Line<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Line<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 3],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Line<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Line<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Line<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Line<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Line");
        for (b, c) in <Line as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Line {
    const N: usize = 3;
    const NAME: &'static str = "Line";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1", "e2", "e0"];
    type Arr<X: gx::Elem> = [X; 3];
    type Mv<S: gx::Slots, T: gx::Coef> = Line<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 3] {
        [f(0), f(1), f(2)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 3], mut f: impl FnMut(&X) -> Y) -> [Y; 3] {
        [f(&a[0]), f(&a[1]), f(&a[2])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 3],
        b: &[Y; 3],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 3] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2])]
    }
}

