    pub fn pinv(self) -> A::Mv<(Rotor,), T>
    where
        Self: gx::PseudoInverse<Coef = T, Output = A::Mv<(Rotor,), T>>,
    {
        gx::PseudoInverse::pinv(self)
    }

    /// [`Self::pinv`] with singular values below `rcond` times the largest treated as zero.
    #[inline]
