impl<S: gx::Slots, T: gx::Coef> gx::Transform<Line<S, T>> for Point<(), T> {
    type Output = Line<S, T>;
    #[inline(always)]
    fn transform(self, x: Line<S, T>) -> Line<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[2] * v[2];
        let t1 = xv[0] * t0;
        let t2 = xv[1] * t0;
        let t3 = v[0] * v[2];
        let t5 = v[1] * v[2];
        let t6 = xv[1] * t5;
        let t8 = -t1;
        let t9 = -t2;
        let t10 = xv[0].mul_add(t3, t6);
        let t11 = t10 * T::from_i64(2);
        let t12 = xv[2].mul_add(t0, t11);
            return Line { c: gx::slots::from_values::<S, T, 3>([t8, t9, t12]) };
        }
        let m0 = v[2] * v[2];
        let m1 = v[0] * v[2];
        let m2 = v[1] * v[2];
        let m3 = -m0;
        let m4 = m1 * T::from_i64(2);
        let m5 = m2 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Line { c: [(x[0].scale(m3)).0, (x[1].scale(m3)).0, (x[0].scale(m4) + x[1].scale(m5) + x[2].scale(m0)).0] }
    }
}

