impl<S: gx::Slots, T: gx::Coef> gx::Transform<Rotor<S, T>> for Point<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Rotor<S, T>) -> Motor<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 2>(&x.c) {
        let t0 = v[2] * xv[1];
        let t1 = v[2] * v[2];
        let t2 = xv[0] * t1;
        let t3 = v[2] * t0;
        let t4 = v[0] * t0;
        let t5 = v[1] * t0;
        let t6 = t4 * T::from_i64(2);
        let t7 = t5 * T::from_i64(2);
            return Motor { c: gx::slots::from_values::<S, T, 4>([t2, t3, t6, t7]) };
        }
        let m0 = v[2] * v[2];
        let m1 = v[0] * v[2];
        let m2 = v[1] * v[2];
        let m3 = m1 * T::from_i64(2);
        let m4 = m2 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[1].scale(m3)).0, (x[1].scale(m4)).0] }
    }
}

