impl<S: gx::Slots, T: gx::Coef> gx::Transform<Line<S, T>> for Rotor<(), T> {
    type Output = Line<S, T>;
    #[inline(always)]
    fn transform(self, x: Line<S, T>) -> Line<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = v[0] * v[1];
        let t3 = t0 - t1;
        let t4 = t0 + t1;
        let t6 = xv[1] * t2;
        let t7 = xv[0] * t2;
        let t8 = xv[1] * t3;
        let t9 = xv[2] * t4;
        let t10 = t6 * T::from_i64(2);
        let t11 = xv[0].mul_add(t3, t10);
        let t13 = (-t7).mul_add(T::from_i64(2), t8);
            return Line { c: gx::slots::from_values::<S, T, 3>([t11, t13, t9]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[0] * v[1];
        let m3 = m0 - m1;
        let m4 = m2 * T::from_i64(2);
        let m5 = -m4;
        let m6 = m0 + m1;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Line { c: [(x[0].scale(m3) + x[1].scale(m4)).0, (x[0].scale(m5) + x[1].scale(m3)).0, (x[2].scale(m6)).0] }
    }
}

