impl<S: gx::Slots, T: gx::Coef> gx::Transform<Line<S, T>> for Translator<(), T> {
    type Output = Line<S, T>;
    #[inline(always)]
    fn transform(self, x: Line<S, T>) -> Line<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = xv[0] * t0;
        let t2 = xv[1] * t0;
        let t4 = v[0] * v[1];
        let t6 = v[0] * v[2];
        let t7 = xv[0] * t6;
        let t8 = (-xv[1]).mul_add(t4, t7);
        let t9 = t8 * T::from_i64(2);
        let t10 = xv[2].mul_add(t0, t9);
            return Line { c: gx::slots::from_values::<S, T, 3>([t1, t2, t10]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[2];
        let m2 = v[0] * v[1];
        let m3 = m1 * T::from_i64(2);
        let m4 = m2 * T::from_i64(2);
        let m5 = -m4;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Line { c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[0].scale(m3) + x[1].scale(m5) + x[2].scale(m0)).0] }
    }
}

