impl<S: gx::Slots, T: gx::Coef> gx::Transform<Motor<S, T>> for Translator<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Motor<S, T>) -> Motor<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[0] * xv[1];
        let t2 = xv[0] * t0;
        let t3 = xv[1] * t0;
        let t4 = xv[2] * t0;
        let t5 = v[2] * t1;
        let t7 = v[1] * t1;
        let t9 = (-t5).mul_add(T::from_i64(2), t4);
        let t10 = t7 * T::from_i64(2);
        let t11 = xv[3].mul_add(t0, t10);
            return Motor { c: gx::slots::from_values::<S, T, 4>([t2, t3, t9, t11]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[2];
        let m2 = v[0] * v[1];
        let m3 = m1 * T::from_i64(2);
        let m4 = -m3;
        let m5 = m2 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[1].scale(m4) + x[2].scale(m0)).0, (x[1].scale(m5) + x[3].scale(m0)).0] }
    }
}

