        let m1 = v[1] * v[1];
        let m2 = v[0] * v[1];
        let m4 = v[1] * v[2];
        let m6 = v[1] * v[3];
        let m7 = m0 - m1;
        let m8 = m0 + m1;
        let m9 = (-v[0]).mul_add(v[3], m4);
        let m10 = m9 * T::from_i64(2);
        let m11 = m2 * T::from_i64(2);
        let m12 = v[0].mul_add(v[2], m6);
        let m13 = m12 * T::from_i64(2);
