impl<S: gx::Slots, T: gx::Coef> gx::Transform<Line<S, T>> for Flector<(), T> {
    type Output = Line<S, T>;
    #[inline(always)]
    fn transform(self, x: Line<S, T>) -> Line<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = v[0] * v[1];
        let t3 = v[0] * v[2];
        let t6 = v[1] * v[2];
        let t7 = t0 - t1;
        let t8 = (-v[1]).mul_add(v[3], t3);
        let t9 = v[0].mul_add(v[3], t6);
        let t10 = t0 + t1;
        let t12 = xv[1] * t2;
        let t13 = xv[0] * t2;
        let t16 = xv[1] * t9;
        let t18 = t12 * T::from_i64(2);
        let t19 = xv[0].mul_add(t7, t18);
        let t20 = t13 * T::from_i64(2);
        let t21 = (-xv[1]).mul_add(t7, t20);
        let t22 = xv[0].mul_add(t8, t16);
        let t23 = t22 * T::from_i64(2);
        let t24 = (-xv[2]).mul_add(t10, t23);
            return Line { c: gx::slots::from_values::<S, T, 3>([t19, t21, t24]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[0] * v[1];
        let m3 = v[0] * v[2];
        let m6 = v[1] * v[2];
        let m7 = m0 - m1;
        let m8 = m2 * T::from_i64(2);
        let m9 = -m7;
        let m10 = (-v[1]).mul_add(v[3], m3);
        let m11 = m10 * T::from_i64(2);
        let m12 = v[0].mul_add(v[3], m6);
        let m13 = m12 * T::from_i64(2);
        let m14 = m0 + m1;
        let m15 = -m14;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Line { c: [(x[0].scale(m7) + x[1].scale(m8)).0, (x[0].scale(m8) + x[1].scale(m9)).0, (x[0].scale(m11) + x[1].scale(m13) + x[2].scale(m15)).0] }
    }
}

