impl<S: gx::Slots, T: gx::Coef> gx::Transform<Point<S, T>> for Flector<(), T> {
    type Output = Point<S, T>;
    #[inline(always)]
    fn transform(self, x: Point<S, T>) -> Point<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = v[0] * v[1];
        let t4 = v[1] * v[3];
        let t5 = v[0] * v[3];
        let t7 = t0 - t1;
        let t8 = v[0].mul_add(v[2], t4);
        let t9 = (-v[1]).mul_add(v[2], t5);
        let t10 = t0 + t1;
        let t13 = xv[2] * t8;
        let t14 = xv[0] * t2;
        let t17 = xv[2] * t10;
        let t18 = xv[1].mul_add(t2, t13);
        let t19 = t18 * T::from_i64(2);
        let t20 = xv[0].mul_add(t7, t19);
        let t21 = (-xv[2]).mul_add(t9, t14);
        let t22 = t21 * T::from_i64(2);
        let t23 = (-xv[1]).mul_add(t7, t22);
        let t24 = -t17;
            return Point { c: gx::slots::from_values::<S, T, 3>([t20, t23, t24]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[0] * v[1];
        let m4 = v[1] * v[3];
        let m6 = v[1] * v[2];
        let m7 = m0 - m1;
        let m8 = m2 * T::from_i64(2);
        let m9 = v[0].mul_add(v[2], m4);
        let m10 = m9 * T::from_i64(2);
        let m11 = -m7;
        let m12 = (-v[0]).mul_add(v[3], m6);
        let m13 = m12 * T::from_i64(2);
        let m14 = m0 + m1;
        let m15 = -m14;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Point { c: [(x[0].scale(m7) + x[1].scale(m8) + x[2].scale(m10)).0, (x[0].scale(m8) + x[1].scale(m11) + x[2].scale(m13)).0, (x[2].scale(m15)).0] }
    }
}

