impl<S: gx::Slots, T: gx::Coef> gx::Transform<Motor<S, T>> for Flector<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Motor<S, T>) -> Motor<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t3 = v[1] * v[3];
        let t4 = v[0] * v[1];
        let t5 = v[0] * v[3];
        let t7 = t0 + t1;
        let t8 = v[0].mul_add(v[2], t3);
        let t9 = t0 - t1;
        let t10 = (-v[1]).mul_add(v[2], t5);
        let t11 = xv[0] * t7;
        let t12 = xv[1] * t7;
        let t15 = xv[3] * t4;
        let t17 = xv[2] * t4;
        let t19 = -t12;
        let t20 = xv[1].mul_add(t8, t15);
        let t21 = t20 * T::from_i64(2);
        let t22 = xv[2].mul_add(t9, t21);
        let t23 = (-xv[1]).mul_add(t10, t17);
        let t24 = t23 * T::from_i64(2);
        let t25 = (-xv[3]).mul_add(t9, t24);
            return Motor { c: gx::slots::from_values::<S, T, 4>([t11, t19, t22, t25]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[0] * v[1];
        let m4 = v[1] * v[3];
        let m6 = v[1] * v[2];
        let m7 = m0 - m1;
        let m8 = m0 + m1;
        let m9 = -m8;
        let m10 = v[0].mul_add(v[2], m4);
        let m11 = m10 * T::from_i64(2);
        let m12 = m2 * T::from_i64(2);
        let m13 = (-v[0]).mul_add(v[3], m6);
        let m14 = m13 * T::from_i64(2);
        let m15 = -m7;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m8)).0, (x[1].scale(m9)).0, (x[1].scale(m11) + x[2].scale(m7) + x[3].scale(m12)).0, (x[1].scale(m14) + x[2].scale(m12) + x[3].scale(m15)).0] }
    }
}

